nt)ceil((strtotime($campaign['ends_at'])-strtotime($campaign['starts_at']))/86400)); $total=(int)$campaign['daily_budget_minor']*$duration; ?><form method="post" action="<?= base_url('marketing/ai_ads/publish_campaign'); ?>" onsubmit="return confirm('Publish this ad on Meta? The lifetime campaign budget is ₦<?= number_format($total/100,0); ?> for <?= $duration; ?> days. Meta bills this spend directly to your ad account.');"><input type="hidden" name="<?= html_escape($csrfName); ?>" value="<?= html_escape($csrfHash); ?>"><input type="hidden" name="campaign_id" value="<?= (int)$campaign['id']; ?>"><input type="hidden" name="confirmed_total_minor" value="<?= $total; ?>"><label><input type="checkbox" name="approve_spend" value="1" required> I approve up to ₦<?= number_format($total/100,0); ?> total spend</label><button class="aiads-button primary" type="submit" <?= empty($has_ads_access)||empty($connection['ad_account_id'])||empty($campaign['media_asset_id'])?'disabled':''; ?>>Publish ad</button></form><?php elseif($campaign['status']==='active'): ?><form method="post" action="<?= base_url('marketing/ai_ads/pause_campaign'); ?>"><input type="hidden" name="<?= html_escape($csrfName); ?>" value="<?= html_escape($csrfHash); ?>"><input type="hidden" name="campaign_id" value="<?= (int)$campaign['id']; ?>"><button class="aiads-button secondary">Pause ad</button></form><?php endif; ?><?php if(!empty($campaign['insights'])): $stats=$campaign['insights']; ?><small>Last 7 days: <?= number_format((int)($stats['impressions']??0)); ?> impressions · <?= number_format((int)($stats['clicks']??0)); ?> clicks · ₦<?= number_format((float)($stats['spend']??0),2); ?> spend</small><?php if(!empty($campaign['result_events'])): ?><small>Results attributed by Meta: <?= number_format((int)($campaign['result_events']['purchases']??0)); ?> purchases · <?= number_format((int)($campaign['result_events']['leads']??0)); ?> leads · <?= number_format((int)($campaign['result_events']['conversations']??0)); ?> conversations</small><?php endif; ?><?php endif; ?></article><?php endforeach; ?></div><?php endif; ?>
