<script>(function(){var b=document.getElementById('aiads-generate'),f=document.getElementById('aiads-copy-form'),s=document.getElementById('aiads-copy-status');if(!b||!f)return;b.addEventListener('click',function(){var p=document.getElementById('aiads-prompt').value.trim();if(!p){s.textContent='Describe your ad first.';return}b.disabled=true;s.textContent='Generating suggestions…';var data=new URLSearchParams();data.append('<?= html_escape($csrfName); ?>','<?= html_escape($csrfHash); ?>');data.append('prompt',p);data.append('product_id',document.getElementById('aiads-product').value);fetch('<?= base_url('marketing/ai_ads/generate_copy'); ?>',{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded'},body:data.toString(),credentials:'same-origin'}).then(function(r){return r.json()}).then(function(r){if(!r.success)throw new Error(r.message||'Could not generate copy.');document.getElementById('aiads-headline').value=r.copy.headline;document.getElementById('aiads-body').value=r.copy.body;s.textContent='Review and edit the suggestion before saving.'+(r.usage?' ('+r.usage.used+' of '+r.usage.limit+' used this plan month).':'')}).catch(function(e){s.textContent=e.message||'AI copy is unavailable.'}).finally(function(){b.disabled=false})})})();</script>
<script>(function(){try{var plan=JSON.parse(sessionStorage.getItem('mp_ai_ads_director')||'null');if(plan){var h=document.getElementById('aiads-headline'),t=document.getElementById('aiads-body'),p=document.getElementById('aiads-prompt');if(h&&plan.headline)h.value=plan.headline;if(t&&plan.primary_text)t.value=plan.primary_text;if(p&&plan.prompt)p.value=plan.prompt;sessionStorage.removeItem('mp_ai_ads_director');var s=document.getElementById('aiads-copy-status');if(s)s.textContent='AI video copy is ready. Review and edit before saving your draft.'}}catch(e){}var mf=document.getElementById('aiads-media-form'),ms=document.getElementById('aiads-media-status');if(mf)mf.addEventListener('submit',function(e){e.preventDefault();var b=mf.querySelector('button[type=submit]');b.disabled=true;ms.textContent='Creating your creative… This may take a minute.';fetch('<?= base_url('marketing/ai_ads/generate_media'); ?>',{method:'POST',body:new URLSearchParams(new FormData(mf)),credentials:'same-origin'}).then(function(r){return r.json()}).then(function(r){if(!r.success)throw new Error(r.message||'Could not create the creative.');if(r.director)sessionStorage.setItem('mp_ai_ads_director',JSON.stringify(r.director));ms.textContent='Creative added to your media. Reloading…';window.location.reload()}).catch(function(e){ms.textContent=e.message||'Creative generation is unavailable.';b.disabled=false})});var uf=document.getElementById('aiads-upload-form'),us=document.getElementById('aiads-upload-status');if(uf)uf.addEventListener('submit',function(e){e.preventDefault();var b=uf.querySelector('button[type=submit]');b.disabled=true;us.textContent='Uploading…';fetch('<?= base_url('marketing/ai_ads/upload_media'); ?>',{method:'POST',body:new FormData(uf),credentials:'same-origin'}).then(function(r){return r.json()}).then(function(r){if(!r.success)throw new Error(r.message||'Could not add media.');window.location.reload()}).catch(function(e){us.textContent=e.message||'Upload failed.';b.disabled=false})})})();</script>
